statement:
Given `n`, return a list of `2^n` integers that forms an `n`-bit Gray code:

- each value lies between `0` and `2^n - 1` inclusive, and no value is repeated (so every such value appears exactly once);
- the list starts with `0`;
- any two neighbouring values differ in exactly one bit of their binary form;
- the last value and the first value also differ in exactly one bit.

Several lists satisfy these rules; any one of them is accepted.

checker:
function check(input, actual, expected) {
  const n = input[0];
  const total = 1 << n;
  if (!Array.isArray(actual) || actual.length !== total || actual[0] !== 0) return false;
  const seen = new Set();
  const oneBit = (a, b) => { const diff = a ^ b; return diff !== 0 && (diff & (diff - 1)) === 0; };
  for (let i = 0; i < total; i++) {
    const value = actual[i];
    if (!Number.isInteger(value) || value < 0 || value >= total || seen.has(value)) return false;
    seen.add(value);
    if (!oneBit(value, actual[(i + 1) % total])) return false;
  }
  return true;
}

validator:
function validate([n]) {
  if (!Number.isInteger(n) || n < 1 || n > 15) return 'n is an integer from 1 to 15 here (the n = 16 answer is too large to show).';
  return null;
}

