function grayCode(n) {
  const total = 1 << n;
  const result = [];
  for (let i = 0; i < total; i++) {
    const gray = i ^ (i >> 1);
    result.push(gray);
  }
  return result;
}

brute:
function grayCode(n) {
  // Build the sequence by reflection: the codes so far, then the same codes in reverse with a new top bit set.
  let codes = [0];
  for (let width = 1; width <= n; width++) {
    const top = Math.pow(2, width - 1);
    const mirrored = [];
    for (let k = codes.length - 1; k >= 0; k--) mirrored.push(codes[k] + top);
    codes = codes.concat(mirrored);
  }
  return codes;
}

